-- Categories
insert into public.categories (id, name, slug, short_description, description, thread_color, sort_order) values ('c0000000-0000-4000-8000-000000000001', 'Language and Linguistics', 'language-and-linguistics', 'Structure, use and change in language, with attention to African languages and Englishes.', 'Studies of the structure, acquisition, use and change of language: phonology, syntax, semantics, pragmatics, sociolinguistics, discourse analysis and applied linguistics. JHTS particularly welcomes work on Nigerian and other African languages, on Nigerian English and World Englishes, and on multilingual practice in classrooms, media and public life.', '--thread-language', 1) on conflict (id) do nothing;
insert into public.categories (id, name, slug, short_description, description, thread_color, sort_order) values ('c0000000-0000-4000-8000-000000000002', 'Literature and Literary Studies', 'literature-and-literary-studies', 'Close reading, literary history and theory across oral and written traditions.', 'Criticism and scholarship on literatures in any language and period: fiction, poetry, drama, life writing and oral literature. We welcome close reading, literary history, theory and comparative work, and studies that place African literatures in conversation with other traditions.', '--thread-literature', 2) on conflict (id) do nothing;
insert into public.categories (id, name, slug, short_description, description, thread_color, sort_order) values ('c0000000-0000-4000-8000-000000000003', 'Cultural and Transcultural Studies', 'cultural-and-transcultural-studies', 'How ideas, forms and identities travel, meet and change across borders.', 'Research on how cultural forms, ideas and identities move across borders and are remade in the process: diaspora, migration, hybridity, popular culture, material culture, religion and ritual, and the politics of representation. This is the journal’s home ground, and interdisciplinary approaches are encouraged.', '--thread-culture', 3) on conflict (id) do nothing;
insert into public.categories (id, name, slug, short_description, description, thread_color, sort_order) values ('c0000000-0000-4000-8000-000000000004', 'Communication and Media Studies', 'communication-and-media-studies', 'Media, rhetoric and communication in print, broadcast and digital cultures.', 'Studies of communication in its social settings: journalism, broadcasting, film, digital and social media, rhetoric, public relations and development communication, including the language and ethics of media in Nigeria and beyond.', '--thread-communication', 4) on conflict (id) do nothing;
insert into public.categories (id, name, slug, short_description, description, thread_color, sort_order) values ('c0000000-0000-4000-8000-000000000005', 'Translation Studies', 'translation-studies', 'Translation and interpreting as practice, theory and cultural exchange.', 'Work on translation and interpreting as linguistic practice, as theory and as cultural exchange: literary and technical translation, translation between African and European languages, self-translation, localisation and the history of translation.', '--thread-translation', 5) on conflict (id) do nothing;
insert into public.categories (id, name, slug, short_description, description, thread_color, sort_order) values ('c0000000-0000-4000-8000-000000000006', 'Philosophy, History and the Arts', 'philosophy-history-and-the-arts', 'Ideas, the past and creative practice, read through the humanities.', 'Philosophical, historical and arts-based scholarship: African and comparative philosophy, intellectual and cultural history, art history, music, theatre and performance studies, and the visual arts.', '--thread-philosophy', 6) on conflict (id) do nothing;
insert into public.categories (id, name, slug, short_description, description, thread_color, sort_order) values ('c0000000-0000-4000-8000-000000000007', 'Education and Society', 'education-and-society', 'Language, literacy and learning in their social and institutional settings.', 'Research on education as a social practice: language and literacy education, English for academic purposes, the teaching of the general studies curriculum, curriculum and policy, and the role of the humanities in public life.', '--thread-education', 7) on conflict (id) do nothing;
insert into public.categories (id, name, slug, short_description, description, thread_color, sort_order) values ('c0000000-0000-4000-8000-000000000008', 'Other Areas of the Humanities', 'other-areas-of-the-humanities', 'Original humanities scholarship that crosses or sits outside these areas.', 'JHTS also publishes sound humanities scholarship that crosses or sits outside the areas above. If you are unsure whether your work fits, please contact the editorial office before submitting.', '--thread-other', 8) on conflict (id) do nothing;

