-- Pages and policies
insert into public.pages (id, kind, slug, title, summary, body_html, sort_order) values ('d5fc2e54-39ed-520c-ad98-c08044ddf6bb', 'page', 'about', 'About the Journal', 'A peer-reviewed, open-access quarterly of the humanities and transcultural studies, published from Nsukka.', '<h2>A home for humanities scholarship</h2>
<p>The <em>Journal of Humanities and Transcultural Studies</em> (JHTS) gives scholars a platform for original research across the humanities. It was established in 2026 by the Use of English Unit of the School of General Studies, University of Nigeria, Nsukka (UNN).</p>
<p>“Transcultural” names the journal’s central interest: ideas crossing borders and being woven together. JHTS publishes work on language, literature, culture, communication, translation, philosophy, history, the arts and education, and it especially welcomes scholarship that moves between languages, cultures and disciplines.</p>
<h2>Purpose</h2>
<p>The journal strengthens the research culture of the Use of English Unit. It develops editorial and peer-review skills among lecturers, mentors emerging scholars and encourages work across disciplines. It also raises the visibility of the Unit, the School of General Studies and UNN, and opens partnerships with scholars and institutions in Nigeria and abroad.</p>
<h2>Publisher</h2>
<p>JHTS is published by the Use of English Unit, School of General Studies, University of Nigeria, Nsukka.</p>
<h2>Frequency and format</h2>
<p>JHTS is published quarterly, in March, June, September and December, as an electronic-only journal. Accepted articles may appear online as Articles in Press before their issue is complete.</p>
<h2>Open access</h2>
<p>All JHTS content is freely available to read, download and share immediately on publication, with no charge to readers or their institutions. Articles are published under the Creative Commons Attribution 4.0 International licence (CC BY 4.0) <mark class="to-confirm">[TO CONFIRM]</mark>, so others may share and adapt the work provided the authors and the journal are credited.</p>
<h2>ISSN and DOI</h2>
<p>The ISSN is in process. Digital Object Identifiers (DOIs) will be assigned to every article once the journal joins Crossref <mark class="to-confirm">[TO CONFIRM]</mark>.</p>
<h2>Indexing</h2>
<p>Indexing and abstracting services <mark class="to-confirm">[TO CONFIRM]</mark>.</p>', 0) on conflict (kind, slug) do nothing;
insert into public.pages (id, kind, slug, title, summary, body_html, sort_order) values ('130b3563-3b94-56a5-8fa8-0af99fcbb831', 'page', 'aims-and-scope', 'Aims and Scope', 'Eight subject areas, four article types, and scholars at every stage of their careers.', '<p>JHTS publishes original, unpublished scholarship across the humanities, with a particular interest in work that crosses borders between languages, cultures and disciplines. Every submission is screened by the editors, checked for plagiarism and sent for double-blind peer review.</p>', 0) on conflict (kind, slug) do nothing;
insert into public.pages (id, kind, slug, title, summary, body_html, sort_order) values ('857bf955-8c51-5f86-85d9-6ebdbc317a8e', 'page', 'use-of-english-unit', 'The Use of English Unit', 'The home of JHTS within the School of General Studies, University of Nigeria, Nsukka.', '<p>JHTS is published by the Use of English Unit of the School of General Studies at the University of Nigeria, Nsukka.</p>
<h2>The Unit</h2>
<p>History of the Use of English Unit, its founding and its development <mark class="to-confirm">[TO CONFIRM]</mark></p>
<p>The Unit’s teaching role: courses taught, number of students served each year and the departments involved <mark class="to-confirm">[TO CONFIRM]</mark></p>
<h2>The School of General Studies</h2>
<p>The School of General Studies, its mandate within UNN and its relationship to the Unit <mark class="to-confirm">[TO CONFIRM]</mark></p>
<h2>The Unit and the journal</h2>
<p>JHTS strengthens the research culture of the Use of English Unit. It develops editorial and peer-review skills among lecturers, mentors emerging scholars and encourages work across disciplines. It also raises the visibility of the Unit, the School of General Studies and UNN, and opens partnerships with scholars and institutions in Nigeria and abroad.</p>
<p>The Editor-in-Chief serves a five-year term that is separate from the office of the Coordinator of the Use of English Unit.</p>
<h2>Coordinator</h2>
<p>Name and title of the current Coordinator of the Unit <mark class="to-confirm">[TO CONFIRM]</mark></p>', 0) on conflict (kind, slug) do nothing;
insert into public.pages (id, kind, slug, title, summary, body_html, sort_order) values ('f25d5f81-0a8a-5e53-b79d-8825b4089ea8', 'page', 'author-guidelines', 'Author Guidelines', 'How to prepare and submit a manuscript to JHTS.', '<h2>Originality</h2>
<p>Manuscripts must be original and unpublished, and must not be under review elsewhere at the same time.</p>
<h2>Formatting</h2>
<p>Prepare your manuscript in Microsoft Word (.docx), set in Times New Roman, 12 point, double-spaced throughout, with page numbers.</p>
<h2>Referencing</h2>
<p>Use either APA 7th edition or MLA 9th edition, consistently throughout the paper. Tell us which style you used when you submit.</p>
<h2>Recommended structure for research articles</h2>
<ol>
<li>Title page (uploaded as a separate file)</li>
<li>Abstract of 150 to 250 words</li>
<li>Three to six keywords</li>
<li>Introduction</li>
<li>Literature review</li>
<li>Theoretical framework</li>
<li>Methodology</li>
<li>Analysis and discussion</li>
<li>Conclusion</li>
<li>References (APA) or Works Cited (MLA)</li>
</ol>
<p>Theoretical papers and critical reviews may depart from this structure where the argument requires it.</p>
<h2>Length</h2>
<ul>
<li>Research articles and theoretical papers: word limit <mark class="to-confirm">[TO CONFIRM]</mark></li>
<li>Critical reviews: word limit <mark class="to-confirm">[TO CONFIRM]</mark></li>
<li>Book reviews: word limit <mark class="to-confirm">[TO CONFIRM]</mark></li>
</ul>
<h2>Double-blind review</h2>
<p>Review at JHTS is double-blind: reviewers do not know who the authors are, and authors do not know who reviewed their work. Remove all author names, affiliations, acknowledgements and other identifying details from the manuscript file, including from the document properties. Author details go in the submission form and on the separate title page only.</p>
<h2>Book reviews</h2>
<p>Book reviews follow separate guidelines. A review should give the full bibliographic details of the book (author, title, publisher, year, ISBN and number of pages), summarise its argument, assess its contribution and say who will find it useful. Please contact the Book Review Editors before writing an unsolicited review <mark class="to-confirm">[TO CONFIRM]</mark>.</p>
<h2>The review process</h2>
<p>Screening → plagiarism check → peer review → decision → revisions → acceptance → publication fee → copy-editing and typesetting → publication.</p>
<p>You can follow each stage from your author dashboard, and we will email you whenever the status of your submission changes.</p>', 0) on conflict (kind, slug) do nothing;
insert into public.pages (id, kind, slug, title, summary, body_html, sort_order) values ('8f1f2f81-a5db-5a07-8203-5a7b5a968e7c', 'page', 'fees-and-payment', 'Fees and Payment', 'Two transparent fees, what they cover and how to pay.', '<h2>Payment methods</h2>
<p>Fees are paid securely online through Paystack by card, bank transfer or USSD. JHTS never sees or stores your card details. You receive an emailed receipt and can download it from your dashboard at any time.</p>
<h2>Refunds</h2>
<p>Refund policy <mark class="to-confirm">[TO CONFIRM]</mark></p>
<h2>Waivers</h2>
<p>Waivers may be granted at the editors’ discretion.</p>', 0) on conflict (kind, slug) do nothing;
insert into public.pages (id, kind, slug, title, summary, body_html, sort_order) values ('7911032b-e51f-516f-bc3e-064a7f14fca9', 'page', 'contact', 'Contact', 'Write to the JHTS editorial office.', '<p>For questions about submissions, reviews, payments or the journal in general, write to the editorial office using the form on this page. We aim to reply within three working days <mark class="to-confirm">[TO CONFIRM]</mark>.</p>', 0) on conflict (kind, slug) do nothing;
insert into public.pages (id, kind, slug, title, summary, body_html, sort_order) values ('fe3f30bd-afe7-5194-838b-cd03a84cf3d3', 'policy', 'publication-ethics', 'Publication Ethics and Malpractice', 'Our commitments, and what we expect of authors, reviewers and editors.', '<p>JHTS follows the Core Practices of the Committee on Publication Ethics (COPE). This statement sets out the duties of everyone involved in publishing with the journal. <mark class="to-confirm">[TO CONFIRM]</mark></p>
<h2>Editors</h2>
<ul>
<li>Judge manuscripts only on their scholarly merit, originality, clarity and relevance to the journal’s scope, without regard to the authors’ race, sex, religion, ethnic origin, citizenship, institution or political views.</li>
<li>Keep submitted manuscripts confidential, sharing them only with reviewers and editorial staff.</li>
<li>Declare conflicts of interest and step aside from any manuscript where one exists.</li>
<li>Never let payment of fees influence an editorial decision.</li>
</ul>
<h2>Reviewers</h2>
<ul>
<li>Review objectively and courteously, giving reasons for their judgements.</li>
<li>Keep manuscripts confidential and never use unpublished material for their own work.</li>
<li>Decline any review where they have a conflict of interest or cannot respond in time.</li>
</ul>
<h2>Authors</h2>
<ul>
<li>Submit only original work that has not been published and is not under review elsewhere.</li>
<li>Cite the work of others accurately and obtain permission for any copyrighted material they reproduce.</li>
<li>List as authors all, and only, those who made a significant contribution.</li>
<li>Disclose funding and any conflicts of interest, and promptly report significant errors they discover in their published work.</li>
</ul>
<h2>Handling misconduct</h2>
<p>Allegations of misconduct, including plagiarism, data fabrication, duplicate submission and citation manipulation, are investigated following COPE flowcharts. Outcomes may include rejection, correction, retraction, or notifying the author’s institution.</p>', 1) on conflict (kind, slug) do nothing;
insert into public.pages (id, kind, slug, title, summary, body_html, sort_order) values ('e8b11158-925d-53e0-a642-641f28e44fef', 'policy', 'peer-review', 'Peer Review Policy', 'Every research submission receives double-blind review by independent experts.', '<p>JHTS uses double-blind peer review: reviewers do not know the identity of the authors, and authors do not know the identity of the reviewers. <mark class="to-confirm">[TO CONFIRM]</mark></p>
<h2>The process</h2>
<ol>
<li><strong>Screening.</strong> The editors check that the manuscript fits the journal’s scope, follows the author guidelines and is properly anonymised.</li>
<li><strong>Plagiarism check.</strong> The manuscript is checked with similarity-detection software (see the Plagiarism and Similarity Checking policy).</li>
<li><strong>Peer review.</strong> The editors invite at least two independent reviewers with expertise in the subject <mark class="to-confirm">[TO CONFIRM]</mark>. Reviewers are asked to respond within a set period <mark class="to-confirm">[TO CONFIRM]</mark>.</li>
<li><strong>Decision.</strong> On the basis of the reviews, the editors accept, ask for minor or major revisions, or reject the manuscript, and send the anonymised reviewer comments to the author.</li>
<li><strong>Revisions.</strong> Revised manuscripts may be returned to the original reviewers.</li>
</ol>
<p>The Editor-in-Chief makes the final decision. Book reviews and editorials are reviewed by the editors rather than external reviewers.</p>
<h2>Appeals</h2>
<p>Authors may appeal a decision by writing to the Editor-in-Chief with a clear explanation of their grounds. Appeals are considered by an editor not involved in the original decision <mark class="to-confirm">[TO CONFIRM]</mark>.</p>', 2) on conflict (kind, slug) do nothing;
insert into public.pages (id, kind, slug, title, summary, body_html, sort_order) values ('d2f44d59-ff57-5e94-8c17-0a9d31fa8472', 'policy', 'authorship', 'Authorship and Contributorship', 'Who qualifies as an author, and how contributions are credited.', '<p>Everyone listed as an author must have made a substantial contribution to the conception, design, research, analysis or interpretation of the work; drafted or critically revised it; approved the final version; and agreed to be accountable for it. <mark class="to-confirm">[TO CONFIRM]</mark></p>
<ul>
<li>People who contributed in other ways, such as technical help, language editing or general supervision, should be thanked in the acknowledgements on the title page.</li>
<li>The corresponding author confirms that all co-authors have seen and approved the manuscript and agree to its submission.</li>
<li>Changes to the author list after submission require the written agreement of every author and the approval of the editors.</li>
<li>Students who submit work based on a thesis or project should acknowledge their supervisors appropriately.</li>
</ul>', 3) on conflict (kind, slug) do nothing;
insert into public.pages (id, kind, slug, title, summary, body_html, sort_order) values ('113f2900-7b43-59e9-bf6e-cfcd701b7bab', 'policy', 'conflicts-of-interest', 'Conflicts of Interest', 'How authors, reviewers and editors declare competing interests.', '<p>A conflict of interest exists when personal, professional or financial considerations could affect, or appear to affect, someone’s judgement. <mark class="to-confirm">[TO CONFIRM]</mark></p>
<ul>
<li><strong>Authors</strong> declare any funding and any relationships that could be seen as influencing their work.</li>
<li><strong>Reviewers</strong> decline to review a manuscript if they recognise the authors’ work and have a close relationship, rivalry or collaboration with them.</li>
<li><strong>Editors</strong> do not handle manuscripts by themselves, their students, close colleagues or relatives. Such manuscripts are handled by another editor, and the editor concerned takes no part in the decision.</li>
</ul>
<p>Submissions from members of the editorial board receive the same double-blind review as any other submission.</p>', 4) on conflict (kind, slug) do nothing;
insert into public.pages (id, kind, slug, title, summary, body_html, sort_order) values ('f8b9072c-7c9f-5b87-973b-884d49adbaa7', 'policy', 'plagiarism', 'Plagiarism and Similarity Checking', 'Every submission is checked for similarity before review.', '<p>Every manuscript is checked with similarity-detection software before peer review <mark class="to-confirm">[TO CONFIRM]</mark>. The editors read the similarity report; a percentage alone does not decide the outcome.</p>
<ul>
<li>Manuscripts with substantial unattributed overlap with other work are rejected.</li>
<li>Authors may be asked to rewrite or properly cite passages with minor overlap.</li>
<li>Re-using one’s own published text without citation (self-plagiarism) is treated in the same way.</li>
<li>Plagiarism discovered after publication is handled under the Corrections, Retractions and Expressions of Concern policy.</li>
</ul>
<p>The similarity report is kept private to the editors.</p>', 5) on conflict (kind, slug) do nothing;
insert into public.pages (id, kind, slug, title, summary, body_html, sort_order) values ('6f099fdc-d92e-58ca-bb6e-e4b949fee77d', 'policy', 'corrections-and-retractions', 'Corrections, Retractions and Expressions of Concern', 'How the published record is kept accurate.', '<p>JHTS keeps the scholarly record accurate, following COPE guidance. <mark class="to-confirm">[TO CONFIRM]</mark></p>
<ul>
<li><strong>Corrections</strong> are published when an error affects part of an article but not its overall findings. The article is updated and a linked correction notice is published.</li>
<li><strong>Retractions</strong> are published when the findings are unreliable, or in cases of plagiarism, duplicate publication or other serious misconduct. The retracted article stays online, clearly marked as retracted, with a notice giving the reason.</li>
<li><strong>Expressions of concern</strong> may be published while an investigation is under way.</li>
</ul>
<p>Anyone who finds an error in a published article should write to the editorial office.</p>', 6) on conflict (kind, slug) do nothing;
insert into public.pages (id, kind, slug, title, summary, body_html, sort_order) values ('8407d45c-a076-5c18-9443-c5ad0eee0090', 'policy', 'open-access-and-licensing', 'Open Access and Licensing', 'Free to read and share, immediately, under CC BY 4.0.', '<p>JHTS is a fully open-access journal. All articles are free to read, download, copy, distribute and print immediately on publication, with no charge to readers. <mark class="to-confirm">[TO CONFIRM]</mark></p>
<p>Articles are published under the <a href="https://creativecommons.org/licenses/by/4.0/">Creative Commons Attribution 4.0 International licence (CC BY 4.0)</a>. Anyone may share and adapt the work for any purpose, provided they give appropriate credit to the authors and to JHTS, link to the licence and say whether changes were made.</p>', 7) on conflict (kind, slug) do nothing;
insert into public.pages (id, kind, slug, title, summary, body_html, sort_order) values ('4f65bc19-c159-5436-9e13-420bbac5b491', 'policy', 'copyright', 'Copyright', 'Authors keep the copyright in their work.', '<p>Authors who publish with JHTS keep the copyright in their work and grant the journal the right of first publication under the CC BY 4.0 licence. <mark class="to-confirm">[TO CONFIRM]</mark></p>
<ul>
<li>Authors may deposit the published version in institutional or subject repositories and share it on personal websites, with a citation to the original publication in JHTS.</li>
<li>Authors are responsible for obtaining permission to reproduce any material, such as images or long quotations, for which they do not hold the copyright.</li>
</ul>', 8) on conflict (kind, slug) do nothing;
insert into public.pages (id, kind, slug, title, summary, body_html, sort_order) values ('f1683e1f-ea5a-568c-ac71-b6668b9a1a63', 'policy', 'digital-preservation', 'Digital Preservation and Archiving', 'How JHTS makes sure its articles remain available.', '<p>JHTS is committed to keeping its content permanently available. <mark class="to-confirm">[TO CONFIRM]</mark></p>
<ul>
<li>The journal will apply to deposit its content with a dedicated preservation service, such as the PKP Preservation Network or LOCKSS <mark class="to-confirm">[TO CONFIRM]</mark>.</li>
<li>The database is backed up daily by the hosting provider, and a full export of the database and all published files is made every week to separate storage owned by the journal.</li>
<li>Authors are encouraged to deposit their published articles in their institutional repositories.</li>
</ul>', 9) on conflict (kind, slug) do nothing;
insert into public.pages (id, kind, slug, title, summary, body_html, sort_order) values ('7e5ed010-33f7-5020-bb4c-8adb23cd05ab', 'policy', 'privacy', 'Privacy Policy', 'What personal data we collect, why, and your rights.', '<p>This policy explains how JHTS handles personal data, in line with the Nigeria Data Protection Act 2023 <mark class="to-confirm">[TO CONFIRM]</mark>.</p>
<h2>What we collect</h2>
<ul>
<li><strong>Account details:</strong> your name, email address, affiliation and, optionally, your ORCID iD.</li>
<li><strong>Submission details:</strong> manuscripts, co-author details and correspondence with the editors.</li>
<li><strong>Payment records:</strong> the amount, date, reference and status of each payment. Card details are handled entirely by Paystack and never reach us.</li>
<li><strong>Usage statistics:</strong> anonymous counts of article views and downloads. We store a daily-changing hashed session code, not your IP address.</li>
</ul>
<h2>Why we use it</h2>
<p>We use your data only to run the journal: to manage submissions and peer review, process fees, send you updates about your work and publish accepted articles.</p>
<h2>Cookies</h2>
<p>The site uses only essential cookies needed to keep you signed in. It does not use advertising or tracking cookies.</p>
<h2>Your rights</h2>
<p>You may ask to see, correct or delete your personal data by writing to the editorial office. Published articles and financial records must be kept for the scholarly record and for audit purposes.</p>
<h2>Retention</h2>
<p>How long submission files and records of rejected submissions are kept <mark class="to-confirm">[TO CONFIRM]</mark></p>', 10) on conflict (kind, slug) do nothing;
insert into public.pages (id, kind, slug, title, summary, body_html, sort_order) values ('c7d708cd-5b51-525f-97d7-ff7a1fd52896', 'policy', 'fees-and-refunds', 'Fees and Refunds', 'What the fees pay for, when they are due and when they are refunded.', '<p>Fees are subject to approval by the university <mark class="to-confirm">[TO CONFIRM]</mark>.</p>
<ul>
<li><strong>Review and plagiarism-check fee</strong>, paid at submission.</li>
<li><strong>Publication fee</strong>, paid only after a manuscript has been accepted.</li>
</ul>
<p>The fees cover review administration, similarity checking, copy-editing, formatting, production and website maintenance.</p>
<p><strong>Payment of fees does not guarantee acceptance. All editorial decisions are based solely on scholarly merit.</strong></p>
<h2>Refunds</h2>
<p>Refund policy <mark class="to-confirm">[TO CONFIRM]</mark></p>
<h2>Waivers</h2>
<p>Waivers may be granted at the editors’ discretion.</p>', 11) on conflict (kind, slug) do nothing;

-- Call for Papers (one active)
insert into public.call_for_papers (id, title, target_label, summary_html, banner_text, submission_deadline, review_period, publication_month, is_active) values ('340d3aa5-4a3a-52dd-88a2-8f2b3fd402fd', 'Call for Papers: Volume 1, Issue 1', 'Vol. 1 No. 1 (March 2027)', '<p>The Journal of Humanities and Transcultural Studies invites original research articles, theoretical papers, critical reviews and book reviews for its inaugural issue. Submissions are welcome across all eight subject areas of the journal, from language and linguistics to education and society. We are especially interested in work that crosses borders between languages, cultures and disciplines.</p><p>Scholars, researchers, and undergraduate and postgraduate students are all welcome to submit. Every manuscript is screened by the editors, checked for plagiarism and sent for double-blind peer review.</p>', 'Now accepting submissions for the inaugural issue.', '2027-01-15T23:59:00+01:00', 'January to February 2027 [TO CONFIRM]', 'March 2027', true) on conflict (id) do nothing;

-- SAMPLE volumes, issues and articles
insert into public.volumes (id, number, year, is_sample) values ('52bb8234-51ce-5de0-9d64-32119715c483', 1, 2027, true) on conflict (number) do nothing;
insert into public.volumes (id, number, year, is_sample) values ('2c2044ec-efaf-550b-9b5d-a4248f624d5e', 2, 2028, true) on conflict (number) do nothing;
insert into public.issues (id, volume_id, number, month, editorial, status, published_at, is_sample) values ('6c8c1914-5e0e-5c1a-a1e6-42f490d4f9ba', '52bb8234-51ce-5de0-9d64-32119715c483', 1, 3, '<p>This inaugural issue sets out the journal’s concerns: language as it is lived in Nigerian classrooms and markets, literature that crosses borders, and the habits of translation that make a shared intellectual life possible. The four articles collected here differ in method, but each asks how meaning travels and what it carries with it.</p><p>As always, every article in this issue was screened by the editors, checked for similarity and read by two independent reviewers under double-blind conditions. We thank our reviewers for their generous and careful work, and we invite readers to respond to these essays, in these pages or elsewhere.</p><p class="signature">Editor-in-Chief</p>', 'published', '2027-03-28T09:00:00Z', true) on conflict (id) do nothing;
insert into public.articles (id, issue_id, category_id, type, title, slug, abstract, keywords, first_page, last_page, citation_style, received_at, accepted_at, online_at, published_at, status, sort_order, view_count, download_count, body_html, is_sample) values ('3a64e80e-5ac6-5e78-b96d-708eaa18b5d1', '6c8c1914-5e0e-5c1a-a1e6-42f490d4f9ba', 'c0000000-0000-4000-8000-000000000001', 'research_article', 'Code-Switching and Classroom Authority in Nsukka Secondary Schools', 'code-switching-and-authority-in-nsukka-classrooms', 'Teachers in Nigerian secondary schools routinely move between English and Igbo, yet official policy treats such switching as a lapse. Drawing on forty hours of recorded lessons in four Nsukka schools, this study examines when and why teachers switch codes. The analysis shows that switches into Igbo cluster around discipline, encouragement and the explanation of difficult concepts, while English marks assessment and formal instruction. Rather than undermining authority, code-switching lets teachers manage the classroom on two registers at once. The article argues for language policies that recognise this practice as a pedagogical resource.', array['code-switching', 'Igbo', 'classroom discourse', 'language policy', 'Nigerian English']::text[], 1, 22, 'apa7', '2026-11-28', '2027-02-16', '2027-03-28T09:00:00Z', '2027-03-28T09:00:00Z', 'published', 1, 1840, 612, null, true) on conflict (id) do nothing;
insert into public.article_authors (article_id, position, name, affiliation, orcid, is_corresponding) values ('3a64e80e-5ac6-5e78-b96d-708eaa18b5d1', 1, 'Adaeze N. Okafor', 'Department of Linguistics, Sample University (SAMPLE)', '0000-0002-1825-0097', true);
insert into public.article_authors (article_id, position, name, affiliation, orcid, is_corresponding) values ('3a64e80e-5ac6-5e78-b96d-708eaa18b5d1', 2, 'Tobenna Eze', 'Department of Education, Sample University (SAMPLE)', null, false);
insert into public.articles (id, issue_id, category_id, type, title, slug, abstract, keywords, first_page, last_page, citation_style, received_at, accepted_at, online_at, published_at, status, sort_order, view_count, download_count, body_html, is_sample) values ('34315952-ef4c-5dca-8dd3-6b1b72498592', '6c8c1914-5e0e-5c1a-a1e6-42f490d4f9ba', 'c0000000-0000-4000-8000-000000000002', 'critical_review', 'The Weaver and the Word: Akwete Cloth as Metaphor in Modern Igbo Poetry', 'the-weaver-and-the-word-akwete-cloth-in-igbo-poetry', 'Akwete cloth, woven by women in south-eastern Nigeria, recurs in modern Igbo poetry as an image of memory, labour and continuity. This review traces the motif through the work of several poets writing in Igbo and English since the 1970s, reading the loom as a figure for composition itself. It argues that the weaving metaphor allows poets to claim a feminine, communal model of authorship against the solitary genius of the Romantic tradition.', array['Igbo poetry', 'Akwete', 'metaphor', 'authorship', 'material culture']::text[], 23, 41, 'mla9', '2026-11-28', '2027-02-16', '2027-03-28T09:00:00Z', '2027-03-28T09:00:00Z', 'published', 2, 1205, 388, null, true) on conflict (id) do nothing;
insert into public.article_authors (article_id, position, name, affiliation, orcid, is_corresponding) values ('34315952-ef4c-5dca-8dd3-6b1b72498592', 1, 'Chiamaka R. Obi', 'Department of English and Literary Studies, Sample University (SAMPLE)', null, true);
insert into public.articles (id, issue_id, category_id, type, title, slug, abstract, keywords, first_page, last_page, citation_style, received_at, accepted_at, online_at, published_at, status, sort_order, view_count, download_count, body_html, is_sample) values ('25f700cc-c8cc-5138-8bc9-be8d93dd1530', '6c8c1914-5e0e-5c1a-a1e6-42f490d4f9ba', 'c0000000-0000-4000-8000-000000000005', 'research_article', 'Loss and Gain in Translating Igbo Proverbs into English', 'translating-proverbs-loss-and-gain', 'Proverbs are among the hardest items to translate, because their force depends on shared cultural knowledge. Using a corpus of 120 Igbo proverbs and their published English translations, this study classifies the strategies translators use, from literal rendering to substitution with an English proverb. Literal translation preserves imagery but often loses the proverb’s pragmatic point, while substitution keeps the point and sacrifices the culture. The article proposes a combined strategy of literal rendering with a brief gloss, and tests it with student readers.', array['translation', 'proverbs', 'Igbo', 'equivalence', 'paremiology']::text[], 42, 63, 'apa7', '2026-11-28', '2027-02-16', '2027-03-28T09:00:00Z', '2027-03-28T09:00:00Z', 'published', 3, 970, 301, null, true) on conflict (id) do nothing;
insert into public.article_authors (article_id, position, name, affiliation, orcid, is_corresponding) values ('25f700cc-c8cc-5138-8bc9-be8d93dd1530', 1, 'Emeka J. Nwosu', 'Department of Foreign Languages, Sample University (SAMPLE)', null, true);
insert into public.article_authors (article_id, position, name, affiliation, orcid, is_corresponding) values ('25f700cc-c8cc-5138-8bc9-be8d93dd1530', 2, 'Halima Bello', 'Department of Translation Studies, Sample University (SAMPLE)', null, false);
insert into public.article_authors (article_id, position, name, affiliation, orcid, is_corresponding) values ('25f700cc-c8cc-5138-8bc9-be8d93dd1530', 3, 'Grace O. Adeyemi', 'Centre for Language Studies, Sample University (SAMPLE)', null, false);
insert into public.articles (id, issue_id, category_id, type, title, slug, abstract, keywords, first_page, last_page, citation_style, received_at, accepted_at, online_at, published_at, status, sort_order, view_count, download_count, body_html, is_sample) values ('42431e14-9b7d-5a5f-9879-b94051a35196', '6c8c1914-5e0e-5c1a-a1e6-42f490d4f9ba', 'c0000000-0000-4000-8000-000000000004', 'theoretical_paper', 'Radio Call-In Programmes and the Making of Public Reason in Nigeria', 'radio-call-in-programmes-and-public-reason', 'Call-in programmes on Nigerian radio give ordinary listeners a rare public platform. This paper develops a theoretical account of these programmes as sites of public reason, drawing on Habermas and on African theories of communal deliberation. It argues that the genre’s conventions, the greeting, the testimony and the presenter’s summing-up, create a distinctive form of reasoned exchange that the idealised public sphere does not capture.', array['radio', 'public sphere', 'deliberation', 'call-in programmes']::text[], 64, 80, 'apa7', '2026-11-28', '2027-02-16', '2027-03-28T09:00:00Z', '2027-03-28T09:00:00Z', 'published', 4, 640, 201, null, true) on conflict (id) do nothing;
insert into public.article_authors (article_id, position, name, affiliation, orcid, is_corresponding) values ('42431e14-9b7d-5a5f-9879-b94051a35196', 1, 'Ibrahim K. Musa', 'Department of Mass Communication, Sample University (SAMPLE)', null, true);
insert into public.issues (id, volume_id, number, month, editorial, status, published_at, is_sample) values ('b7862432-326c-5e16-b127-cda4c71d36ec', '52bb8234-51ce-5de0-9d64-32119715c483', 2, 6, '<p>Our second issue turns to the past and to the ways it is retold: in oral history, in museum catalogues and in the philosophy we teach our students. The contributors share a conviction that the humanities must account for the archives they rely on.</p><p>As always, every article in this issue was screened by the editors, checked for similarity and read by two independent reviewers under double-blind conditions. We thank our reviewers for their generous and careful work, and we invite readers to respond to these essays, in these pages or elsewhere.</p><p class="signature">Editor-in-Chief</p>', 'published', '2027-06-27T09:00:00Z', true) on conflict (id) do nothing;
insert into public.articles (id, issue_id, category_id, type, title, slug, abstract, keywords, first_page, last_page, citation_style, received_at, accepted_at, online_at, published_at, status, sort_order, view_count, download_count, body_html, is_sample) values ('93b8c335-f43f-5527-b9a2-9ecf85d0cffb', 'b7862432-326c-5e16-b127-cda4c71d36ec', 'c0000000-0000-4000-8000-000000000006', 'research_article', 'Oral Testimony and the Nigerian Civil War Archive', 'oral-history-and-the-nigerian-civil-war-archive', 'Official archives of the Nigerian Civil War remain incomplete, and much of what is known survives in family memory. This article analyses thirty oral testimonies collected in Enugu and Anambra States to show how survivors narrate displacement, hunger and return. It argues that oral testimony is not merely a supplement to written records but an archive with its own forms and silences, and it proposes protocols for its ethical use in historical writing.', array['oral history', 'civil war', 'memory', 'archives', 'Nigeria']::text[], 1, 24, 'mla9', '2027-02-27', '2027-05-18', '2027-06-27T09:00:00Z', '2027-06-27T09:00:00Z', 'published', 1, 1510, 540, null, true) on conflict (id) do nothing;
insert into public.article_authors (article_id, position, name, affiliation, orcid, is_corresponding) values ('93b8c335-f43f-5527-b9a2-9ecf85d0cffb', 1, 'Ngozi P. Uche', 'Department of History and International Studies, Sample University (SAMPLE)', null, true);
insert into public.articles (id, issue_id, category_id, type, title, slug, abstract, keywords, first_page, last_page, citation_style, received_at, accepted_at, online_at, published_at, status, sort_order, view_count, download_count, body_html, is_sample) values ('37f1121c-2567-50ad-bda8-acbe404665bb', 'b7862432-326c-5e16-b127-cda4c71d36ec', 'c0000000-0000-4000-8000-000000000006', 'theoretical_paper', 'Ubuntu and the Ethics of Scholarly Collaboration', 'ubuntu-and-the-ethics-of-scholarly-collaboration', 'Academic collaboration is usually governed by rules of credit borrowed from the sciences. This paper asks what an ethics of collaboration grounded in Ubuntu, the southern African idea that a person is a person through other persons, would require of humanities scholars. It argues for practices of shared authorship, mentoring and citation that recognise intellectual work as communal without erasing individual contribution.', array['Ubuntu', 'ethics', 'collaboration', 'authorship', 'African philosophy']::text[], 25, 44, 'apa7', '2027-02-27', '2027-05-18', '2027-06-27T09:00:00Z', '2027-06-27T09:00:00Z', 'published', 2, 880, 260, null, true) on conflict (id) do nothing;
insert into public.article_authors (article_id, position, name, affiliation, orcid, is_corresponding) values ('37f1121c-2567-50ad-bda8-acbe404665bb', 1, 'Samuel A. Okonkwo', 'Department of Philosophy, Sample University (SAMPLE)', null, true);
insert into public.article_authors (article_id, position, name, affiliation, orcid, is_corresponding) values ('37f1121c-2567-50ad-bda8-acbe404665bb', 2, 'Thandiwe M. Dlamini', 'School of Humanities, Sample University (SAMPLE)', null, false);
insert into public.articles (id, issue_id, category_id, type, title, slug, abstract, keywords, first_page, last_page, citation_style, received_at, accepted_at, online_at, published_at, status, sort_order, view_count, download_count, body_html, is_sample) values ('3930e670-f81e-5c43-a6c3-9812e977baf5', 'b7862432-326c-5e16-b127-cda4c71d36ec', 'c0000000-0000-4000-8000-000000000003', 'research_article', 'Museum Labels and the Language of Restitution', 'museum-labels-and-the-language-of-restitution', 'As European museums return looted Benin bronzes, the labels beside the objects have begun to change. This study compares labels from six museums before and after 2020, using critical discourse analysis to trace shifts in agency, voice and tense. It finds that while newer labels name the 1897 expedition as a looting, many still present the objects through the eyes of their collectors. The article suggests principles for co-authored labels.', array['restitution', 'museums', 'discourse analysis', 'Benin bronzes']::text[], 45, 66, 'apa7', '2027-02-27', '2027-05-18', '2027-06-27T09:00:00Z', '2027-06-27T09:00:00Z', 'published', 3, 1320, 415, null, true) on conflict (id) do nothing;
insert into public.article_authors (article_id, position, name, affiliation, orcid, is_corresponding) values ('3930e670-f81e-5c43-a6c3-9812e977baf5', 1, 'Kelechi Anyanwu', 'Department of Fine and Applied Arts, Sample University (SAMPLE)', null, true);
insert into public.articles (id, issue_id, category_id, type, title, slug, abstract, keywords, first_page, last_page, citation_style, received_at, accepted_at, online_at, published_at, status, sort_order, view_count, download_count, body_html, is_sample) values ('ab372416-aab3-560f-a4cb-9ae2c52e873e', 'b7862432-326c-5e16-b127-cda4c71d36ec', 'c0000000-0000-4000-8000-000000000007', 'research_article', 'Student Voice in the General Studies English Classroom', 'general-studies-english-and-student-voice', 'Use of English courses reach every first-year student, yet students rarely shape how they are taught. Through focus groups with 64 students and interviews with eight lecturers, this study explores how students experience the course and what they would change. Students value the course’s practical aims but describe large classes as silencing. The article recommends small-group writing workshops and peer review as ways to restore student voice.', array['general studies', 'academic writing', 'student voice', 'higher education']::text[], 67, 85, 'apa7', '2027-02-27', '2027-05-18', '2027-06-27T09:00:00Z', '2027-06-27T09:00:00Z', 'published', 4, 1105, 489, null, true) on conflict (id) do nothing;
insert into public.article_authors (article_id, position, name, affiliation, orcid, is_corresponding) values ('ab372416-aab3-560f-a4cb-9ae2c52e873e', 1, 'Blessing C. Nnamdi', 'School of General Studies, Sample University (SAMPLE)', null, true);
insert into public.article_authors (article_id, position, name, affiliation, orcid, is_corresponding) values ('ab372416-aab3-560f-a4cb-9ae2c52e873e', 2, 'Uchenna D. Ike', 'Department of Arts Education, Sample University (SAMPLE)', null, false);
insert into public.issues (id, volume_id, number, month, editorial, status, published_at, is_sample) values ('328d9c93-5d7f-5b8b-8ec7-1e07c6927c29', '52bb8234-51ce-5de0-9d64-32119715c483', 3, 9, '<p>This issue gathers work on the screen and the page: Nollywood’s multilingual audiences, the novel of migration and the new forms of reading that phones have made possible. It closes with our first book review.</p><p>As always, every article in this issue was screened by the editors, checked for similarity and read by two independent reviewers under double-blind conditions. We thank our reviewers for their generous and careful work, and we invite readers to respond to these essays, in these pages or elsewhere.</p><p class="signature">Editor-in-Chief</p>', 'published', '2027-09-26T09:00:00Z', true) on conflict (id) do nothing;
insert into public.articles (id, issue_id, category_id, type, title, slug, abstract, keywords, first_page, last_page, citation_style, received_at, accepted_at, online_at, published_at, status, sort_order, view_count, download_count, body_html, is_sample) values ('df920de9-d4d7-549c-8d23-ce7066d21b5f', '328d9c93-5d7f-5b8b-8ec7-1e07c6927c29', 'c0000000-0000-4000-8000-000000000004', 'research_article', 'Subtitles and Multilingual Audiences in Nollywood', 'subtitles-and-multilingual-audiences-in-nollywood', 'Nollywood films increasingly circulate with English subtitles on streaming platforms, reaching viewers who do not speak the languages on screen. This study compares subtitled and original versions of twelve Yoruba- and Igbo-language films to show how subtitling flattens proverbs, honorifics and humour. It argues that subtitles are a site of cultural negotiation and calls for subtitling practices that keep more of the source culture visible.', array['Nollywood', 'subtitling', 'audiovisual translation', 'streaming']::text[], 1, 19, 'apa7', '2027-05-29', '2027-08-17', '2027-09-26T09:00:00Z', '2027-09-26T09:00:00Z', 'published', 1, 1720, 530, null, true) on conflict (id) do nothing;
insert into public.article_authors (article_id, position, name, affiliation, orcid, is_corresponding) values ('df920de9-d4d7-549c-8d23-ce7066d21b5f', 1, 'Funmilayo O. Adebayo', 'Department of Theatre and Film Studies, Sample University (SAMPLE)', null, true);
insert into public.articles (id, issue_id, category_id, type, title, slug, abstract, keywords, first_page, last_page, citation_style, received_at, accepted_at, online_at, published_at, status, sort_order, view_count, download_count, body_html, is_sample) values ('29943254-2291-535d-b413-ee637dd7c6e4', '328d9c93-5d7f-5b8b-8ec7-1e07c6927c29', 'c0000000-0000-4000-8000-000000000002', 'critical_review', 'Coming Home Changed: The Novel of Return in Nigerian Diaspora Fiction', 'the-novel-of-return-in-nigerian-diaspora-fiction', 'A growing body of Nigerian fiction follows characters who return home after years abroad. This review reads five such novels published since 2009 and identifies the conventions of the ‘novel of return’: the airport arrival, the misrecognised accent and the family that has moved on. It argues that these novels use return to examine what the nation expects of its diaspora.', array['diaspora', 'return', 'Nigerian fiction', 'migration']::text[], 20, 37, 'mla9', '2027-05-29', '2027-08-17', '2027-09-26T09:00:00Z', '2027-09-26T09:00:00Z', 'published', 2, 1480, 466, null, true) on conflict (id) do nothing;
insert into public.article_authors (article_id, position, name, affiliation, orcid, is_corresponding) values ('29943254-2291-535d-b413-ee637dd7c6e4', 1, 'Ijeoma S. Chukwu', 'Department of English and Literary Studies, Sample University (SAMPLE)', null, true);
insert into public.articles (id, issue_id, category_id, type, title, slug, abstract, keywords, first_page, last_page, citation_style, received_at, accepted_at, online_at, published_at, status, sort_order, view_count, download_count, body_html, is_sample) values ('120c36ec-f3b1-51c2-ad79-7a37caf3eb0e', '328d9c93-5d7f-5b8b-8ec7-1e07c6927c29', 'c0000000-0000-4000-8000-000000000007', 'research_article', 'Reading on Phones: Undergraduate Reading Habits in a Mobile Age', 'reading-on-phones-among-undergraduates', 'Most Nigerian undergraduates now read set texts on their phones. A survey of 410 students and reading diaries kept by 30 of them reveal how mobile reading shapes attention, annotation and recall. Students read more often but in shorter sessions, and rarely annotate. The study proposes reading tasks designed for mobile readers and argues that libraries should license texts for phone use.', array['reading habits', 'mobile learning', 'undergraduates', 'literacy']::text[], 38, 57, 'apa7', '2027-05-29', '2027-08-17', '2027-09-26T09:00:00Z', '2027-09-26T09:00:00Z', 'published', 3, 990, 310, null, true) on conflict (id) do nothing;
insert into public.article_authors (article_id, position, name, affiliation, orcid, is_corresponding) values ('120c36ec-f3b1-51c2-ad79-7a37caf3eb0e', 1, 'Chinedu P. Okeke', 'Department of Library and Information Science, Sample University (SAMPLE)', null, true);
insert into public.article_authors (article_id, position, name, affiliation, orcid, is_corresponding) values ('120c36ec-f3b1-51c2-ad79-7a37caf3eb0e', 2, 'Amina Yusuf', 'Department of English, Sample University (SAMPLE)', null, false);
insert into public.articles (id, issue_id, category_id, type, title, slug, abstract, keywords, first_page, last_page, citation_style, received_at, accepted_at, online_at, published_at, status, sort_order, view_count, download_count, body_html, is_sample) values ('d7cd8029-cbf8-587c-92cb-b785d4cf5f0d', '328d9c93-5d7f-5b8b-8ec7-1e07c6927c29', 'c0000000-0000-4000-8000-000000000001', 'book_review', 'Review of Languages of the Market: Trade Talk in West Africa', 'review-of-languages-of-the-market', 'A review of a study of the multilingual talk of West African markets, which combines fieldwork in Onitsha, Kano and Accra with an accessible account of how traders build trust across languages.', array['book review', 'markets', 'multilingualism', 'West Africa']::text[], 58, 61, 'apa7', '2027-05-29', '2027-08-17', '2027-09-26T09:00:00Z', '2027-09-26T09:00:00Z', 'published', 4, 420, 98, null, true) on conflict (id) do nothing;
insert into public.article_authors (article_id, position, name, affiliation, orcid, is_corresponding) values ('d7cd8029-cbf8-587c-92cb-b785d4cf5f0d', 1, 'Daniel O. Agu', 'Department of Linguistics, Sample University (SAMPLE)', null, true);
insert into public.book_reviews (article_id, book_title, book_author, publisher, year, isbn, pages) values ('d7cd8029-cbf8-587c-92cb-b785d4cf5f0d', 'Languages of the Market: Trade Talk in West Africa (SAMPLE)', 'R. A. Sample', 'Sample Academic Press', 2026, '978-0-00-000000-1', 248) on conflict (article_id) do nothing;
insert into public.issues (id, volume_id, number, month, editorial, status, published_at, is_sample) values ('2c003cde-6d8c-5996-965f-7f2c7d41a4f9', '52bb8234-51ce-5de0-9d64-32119715c483', 4, 12, '<p>The December issue closes our first volume with essays on festival, performance and the sacred, and on the words we use for them in more than one language.</p><p>As always, every article in this issue was screened by the editors, checked for similarity and read by two independent reviewers under double-blind conditions. We thank our reviewers for their generous and careful work, and we invite readers to respond to these essays, in these pages or elsewhere.</p><p class="signature">Editor-in-Chief</p>', 'published', '2027-12-19T09:00:00Z', true) on conflict (id) do nothing;
insert into public.articles (id, issue_id, category_id, type, title, slug, abstract, keywords, first_page, last_page, citation_style, received_at, accepted_at, online_at, published_at, status, sort_order, view_count, download_count, body_html, is_sample) values ('7d635e16-2794-5f39-bc63-6fb265ce3f68', '2c003cde-6d8c-5996-965f-7f2c7d41a4f9', 'c0000000-0000-4000-8000-000000000003', 'research_article', 'Masquerade Performance and the Urban Crowd', 'masquerade-performance-and-the-urban-crowd', 'Masquerades once performed in village squares now process through crowded city streets, filmed on dozens of phones. Drawing on fieldwork at festivals in Enugu and Nsukka, this article examines how urban audiences reshape masquerade performance, from route and timing to costume. It argues that the masquerade has adapted to the city by becoming a spectacle of circulation, both on the street and online.', array['masquerade', 'performance', 'festival', 'urban culture']::text[], 1, 21, 'mla9', '2027-08-21', '2027-11-09', '2027-12-19T09:00:00Z', '2027-12-19T09:00:00Z', 'published', 1, 1260, 402, null, true) on conflict (id) do nothing;
insert into public.article_authors (article_id, position, name, affiliation, orcid, is_corresponding) values ('7d635e16-2794-5f39-bc63-6fb265ce3f68', 1, 'Obinna T. Nweke', 'Department of Theatre Arts, Sample University (SAMPLE)', null, true);
insert into public.articles (id, issue_id, category_id, type, title, slug, abstract, keywords, first_page, last_page, citation_style, received_at, accepted_at, online_at, published_at, status, sort_order, view_count, download_count, body_html, is_sample) values ('ae450966-5c32-57f6-a04d-385d18020f1d', '2c003cde-6d8c-5996-965f-7f2c7d41a4f9', 'c0000000-0000-4000-8000-000000000005', 'research_article', 'Translating the Sacred: Key Terms in Igbo Bible Translation', 'translating-the-sacred-bible-translation-in-igbo', 'Translators of the Bible into Igbo have had to choose words for God, spirit and sin from a religious vocabulary with its own history. This study compares key terms across three Igbo Bible translations and shows how each choice negotiates between indigenous religious meaning and missionary theology. It concludes that these terms have reshaped both Igbo Christianity and the Igbo language.', array['Bible translation', 'Igbo', 'religious language', 'lexical choice']::text[], 22, 43, 'apa7', '2027-08-21', '2027-11-09', '2027-12-19T09:00:00Z', '2027-12-19T09:00:00Z', 'published', 2, 1010, 333, null, true) on conflict (id) do nothing;
insert into public.article_authors (article_id, position, name, affiliation, orcid, is_corresponding) values ('ae450966-5c32-57f6-a04d-385d18020f1d', 1, 'Peter C. Odo', 'Department of Religion and Cultural Studies, Sample University (SAMPLE)', null, true);
insert into public.article_authors (article_id, position, name, affiliation, orcid, is_corresponding) values ('ae450966-5c32-57f6-a04d-385d18020f1d', 2, 'Mary-Jane Ezike', 'Department of Linguistics, Sample University (SAMPLE)', null, false);
insert into public.articles (id, issue_id, category_id, type, title, slug, abstract, keywords, first_page, last_page, citation_style, received_at, accepted_at, online_at, published_at, status, sort_order, view_count, download_count, body_html, is_sample) values ('8993ce0e-a0bd-5a8a-8c06-dfb8e0304a4a', '2c003cde-6d8c-5996-965f-7f2c7d41a4f9', 'c0000000-0000-4000-8000-000000000006', 'critical_review', 'Highlife Lyrics and the Poetics of Advice', 'highlife-lyrics-and-the-poetics-of-advice', 'Highlife songs often speak in the voice of an elder giving advice. This review surveys the advisory mode in Igbo highlife from the 1960s to the present, reading lyrics as moral philosophy set to music. It argues that the genre’s proverbs, warnings and blessings make it an important and neglected archive of popular ethics.', array['highlife', 'music', 'lyrics', 'popular ethics']::text[], 44, 59, 'mla9', '2027-08-21', '2027-11-09', '2027-12-19T09:00:00Z', '2027-12-19T09:00:00Z', 'published', 3, 780, 199, null, true) on conflict (id) do nothing;
insert into public.article_authors (article_id, position, name, affiliation, orcid, is_corresponding) values ('8993ce0e-a0bd-5a8a-8c06-dfb8e0304a4a', 1, 'Ebuka Nnaji', 'Department of Music, Sample University (SAMPLE)', null, true);
insert into public.articles (id, issue_id, category_id, type, title, slug, abstract, keywords, first_page, last_page, citation_style, received_at, accepted_at, online_at, published_at, status, sort_order, view_count, download_count, body_html, is_sample) values ('cf961415-0bc5-505b-8d5d-6bcba6ce6f5a', '2c003cde-6d8c-5996-965f-7f2c7d41a4f9', 'c0000000-0000-4000-8000-000000000005', 'book_review', 'Review of The Translator’s House: Essays on Language and Belonging', 'review-of-the-translators-house', 'A review of a collection of essays by working translators on the homes, real and imagined, that translation builds between languages.', array['book review', 'translation', 'essays', 'belonging']::text[], 60, 63, 'apa7', '2027-08-21', '2027-11-09', '2027-12-19T09:00:00Z', '2027-12-19T09:00:00Z', 'published', 4, 360, 77, null, true) on conflict (id) do nothing;
insert into public.article_authors (article_id, position, name, affiliation, orcid, is_corresponding) values ('cf961415-0bc5-505b-8d5d-6bcba6ce6f5a', 1, 'Ruth A. Okoro', 'Department of Foreign Languages, Sample University (SAMPLE)', null, true);
insert into public.book_reviews (article_id, book_title, book_author, publisher, year, isbn, pages) values ('cf961415-0bc5-505b-8d5d-6bcba6ce6f5a', 'The Translator’s House: Essays on Language and Belonging (SAMPLE)', 'M. B. Sample (ed.)', 'Sample University Press', 2027, '978-0-00-000000-2', 312) on conflict (article_id) do nothing;
insert into public.issues (id, volume_id, number, month, editorial, status, published_at, is_sample) values ('cf63f04e-daf9-5125-8040-04b6c2ad0c27', '2c2044ec-efaf-550b-9b5d-a4248f624d5e', 1, 3, '<p>We open our second volume with a special focus on language in public life: on signboards, in parliament, and in the slogans that circulate on social media. The essays show how much of politics is conducted in the choice between languages.</p><p>As always, every article in this issue was screened by the editors, checked for similarity and read by two independent reviewers under double-blind conditions. We thank our reviewers for their generous and careful work, and we invite readers to respond to these essays, in these pages or elsewhere.</p><p class="signature">Editor-in-Chief</p>', 'published', '2028-03-26T09:00:00Z', true) on conflict (id) do nothing;
insert into public.articles (id, issue_id, category_id, type, title, slug, abstract, keywords, first_page, last_page, citation_style, received_at, accepted_at, online_at, published_at, status, sort_order, view_count, download_count, body_html, is_sample) values ('0ce23170-d2f3-5616-9208-b6e2722c5253', 'cf63f04e-daf9-5125-8040-04b6c2ad0c27', 'c0000000-0000-4000-8000-000000000001', 'research_article', 'The Linguistic Landscape of Enugu: Signboards, Prestige and Play', 'linguistic-landscape-of-enugu-signboards', 'Shop signs, billboards and posters make language visible in the city. This study photographs and analyses 1,200 signs in three districts of Enugu to map the use of English, Igbo, Nigerian Pidgin and other languages. English dominates official and commercial signs, but Igbo and Pidgin appear in playful and intimate registers, particularly in names and slogans. The article argues that the linguistic landscape shows a division of labour between languages rather than simple English dominance.', array['linguistic landscape', 'Enugu', 'multilingualism', 'Nigerian Pidgin', 'signage']::text[], 1, 24, 'apa7', '2027-11-27', '2028-02-15', '2028-03-26T09:00:00Z', '2028-03-26T09:00:00Z', 'published', 1, 1980, 701, null, true) on conflict (id) do nothing;
insert into public.article_authors (article_id, position, name, affiliation, orcid, is_corresponding) values ('0ce23170-d2f3-5616-9208-b6e2722c5253', 1, 'Nkechi L. Okoli', 'Department of Linguistics, Sample University (SAMPLE)', '0000-0001-5109-3700', true);
insert into public.article_authors (article_id, position, name, affiliation, orcid, is_corresponding) values ('0ce23170-d2f3-5616-9208-b6e2722c5253', 2, 'Yusuf A. Danjuma', 'Department of Languages, Sample University (SAMPLE)', null, false);
insert into public.articles (id, issue_id, category_id, type, title, slug, abstract, keywords, first_page, last_page, citation_style, received_at, accepted_at, online_at, published_at, status, sort_order, view_count, download_count, body_html, is_sample) values ('ee97da73-ae95-5790-bef1-8c76d4675c1b', 'cf63f04e-daf9-5125-8040-04b6c2ad0c27', 'c0000000-0000-4000-8000-000000000004', 'research_article', 'Hashtags and the Grammar of Protest', 'hashtags-and-the-grammar-of-protest', 'Hashtags compress political claims into a few words. Analysing 50,000 posts from three Nigerian protest movements, this study describes the grammar of protest hashtags: their imperatives, their pronouns and their code-mixing. It shows how hashtags build collective identity and argues that their brevity is a resource for mobilisation rather than a limit on argument.', array['hashtags', 'social media', 'protest', 'discourse']::text[], 25, 44, 'apa7', '2027-11-27', '2028-02-15', '2028-03-26T09:00:00Z', '2028-03-26T09:00:00Z', 'published', 2, 1650, 520, null, true) on conflict (id) do nothing;
insert into public.article_authors (article_id, position, name, affiliation, orcid, is_corresponding) values ('ee97da73-ae95-5790-bef1-8c76d4675c1b', 1, 'Zainab O. Lawal', 'Department of Mass Communication, Sample University (SAMPLE)', null, true);
insert into public.articles (id, issue_id, category_id, type, title, slug, abstract, keywords, first_page, last_page, citation_style, received_at, accepted_at, online_at, published_at, status, sort_order, view_count, download_count, body_html, is_sample) values ('b30135f0-6d52-5015-8adc-0cb70ae2ba18', 'cf63f04e-daf9-5125-8040-04b6c2ad0c27', 'c0000000-0000-4000-8000-000000000003', 'theoretical_paper', 'Rethinking Multilingualism in the National Assembly', 'multilingualism-in-the-national-assembly', 'Nigeria’s constitution allows legislators to speak Hausa, Igbo or Yoruba, but English remains the language of the National Assembly. This paper reads parliamentary records alongside theories of linguistic justice to ask what a genuinely multilingual legislature would require. It proposes a model of interpreted debate that treats language rights as part of political representation.', array['linguistic justice', 'parliament', 'language rights', 'representation']::text[], 45, 62, 'apa7', '2027-11-27', '2028-02-15', '2028-03-26T09:00:00Z', '2028-03-26T09:00:00Z', 'published', 3, 870, 244, null, true) on conflict (id) do nothing;
insert into public.article_authors (article_id, position, name, affiliation, orcid, is_corresponding) values ('b30135f0-6d52-5015-8adc-0cb70ae2ba18', 1, 'Oluwaseun T. Bakare', 'Department of Political Science, Sample University (SAMPLE)', null, true);
insert into public.articles (id, issue_id, category_id, type, title, slug, abstract, keywords, first_page, last_page, citation_style, received_at, accepted_at, online_at, published_at, status, sort_order, view_count, download_count, body_html, is_sample) values ('fa045dfb-2838-538f-bcaa-edb96d27f336', 'cf63f04e-daf9-5125-8040-04b6c2ad0c27', 'c0000000-0000-4000-8000-000000000002', 'book_review', 'Review of Writing in Two Tongues: Bilingual African Authors', 'review-of-writing-in-two-tongues', 'A review of a lucid study of African writers who publish in two languages, with chapters on self-translation and on the economics of publishing in African languages.', array['book review', 'bilingualism', 'African literature', 'self-translation']::text[], 63, 66, 'mla9', '2027-11-27', '2028-02-15', '2028-03-26T09:00:00Z', '2028-03-26T09:00:00Z', 'published', 4, 510, 140, null, true) on conflict (id) do nothing;
insert into public.article_authors (article_id, position, name, affiliation, orcid, is_corresponding) values ('fa045dfb-2838-538f-bcaa-edb96d27f336', 1, 'Ifeoma G. Nwachukwu', 'Department of English and Literary Studies, Sample University (SAMPLE)', null, true);
insert into public.book_reviews (article_id, book_title, book_author, publisher, year, isbn, pages) values ('fa045dfb-2838-538f-bcaa-edb96d27f336', 'Writing in Two Tongues: Bilingual African Authors (SAMPLE)', 'K. C. Sample', 'Sample Academic Press', 2027, '978-0-00-000000-3', 276) on conflict (article_id) do nothing;
insert into public.articles (id, issue_id, category_id, type, title, slug, abstract, keywords, first_page, last_page, citation_style, received_at, accepted_at, online_at, published_at, status, sort_order, view_count, download_count, body_html, is_sample) values ('0b159209-56a2-531e-bfea-62630b2ef2d4', null, 'c0000000-0000-4000-8000-000000000004', 'research_article', 'Pidgin News Bulletins and the Reach of Public Radio', 'pidgin-news-and-the-reach-of-radio', 'Public radio stations increasingly broadcast news in Nigerian Pidgin. Combining listener surveys in Warri and Benin City with analysis of bulletin scripts, this study asks whether Pidgin news reaches audiences that English news does not. It finds that Pidgin bulletins significantly widen reach among market traders and artisans, and that listeners judge them as trustworthy as English bulletins.', array['Nigerian Pidgin', 'radio news', 'audiences', 'public broadcasting']::text[], null, null, 'apa7', '2027-12-16', '2028-03-05', '2028-04-14T09:00:00Z', null, 'in_press', 1, 320, 88, null, true) on conflict (id) do nothing;
insert into public.article_authors (article_id, position, name, affiliation, orcid, is_corresponding) values ('0b159209-56a2-531e-bfea-62630b2ef2d4', 1, 'Efe M. Oghene', 'Department of Mass Communication, Sample University (SAMPLE)', null, true);
insert into public.articles (id, issue_id, category_id, type, title, slug, abstract, keywords, first_page, last_page, citation_style, received_at, accepted_at, online_at, published_at, status, sort_order, view_count, download_count, body_html, is_sample) values ('9b853155-2122-5ce4-87c9-82b7e0a881e2', null, 'c0000000-0000-4000-8000-000000000002', 'critical_review', 'Achebe’s English and the Ethics of Translation', 'achebe-and-the-ethics-of-translation', 'Chinua Achebe described his English as ‘a new English, still in full communion with its ancestral home but altered to suit its new African surroundings’. This review reads that claim as an ethics of translation and traces its influence on later Nigerian writers and on translation studies.', array['Achebe', 'translation', 'African English', 'postcolonial literature']::text[], null, null, 'mla9', '2027-12-30', '2028-03-19', '2028-04-28T09:00:00Z', null, 'in_press', 2, 610, 175, null, true) on conflict (id) do nothing;
insert into public.article_authors (article_id, position, name, affiliation, orcid, is_corresponding) values ('9b853155-2122-5ce4-87c9-82b7e0a881e2', 1, 'Chukwudi E. Onu', 'Department of English and Literary Studies, Sample University (SAMPLE)', null, true);
insert into public.article_authors (article_id, position, name, affiliation, orcid, is_corresponding) values ('9b853155-2122-5ce4-87c9-82b7e0a881e2', 2, 'Sarah L. Bennett', 'School of Modern Languages, Sample University (SAMPLE)', null, false);
insert into public.articles (id, issue_id, category_id, type, title, slug, abstract, keywords, first_page, last_page, citation_style, received_at, accepted_at, online_at, published_at, status, sort_order, view_count, download_count, body_html, is_sample) values ('1aa7a20c-039f-596f-82b0-f61bfae8eb54', null, 'c0000000-0000-4000-8000-000000000007', 'theoretical_paper', 'Indigenous Knowledge in the Humanities Curriculum', 'indigenous-knowledge-in-the-humanities-curriculum', 'Calls to decolonise the curriculum often stall at the question of what should be taught instead. This paper proposes a framework for bringing indigenous knowledge into humanities courses without reducing it to folklore, using examples from language, history and philosophy teaching in Nigerian universities.', array['decolonisation', 'curriculum', 'indigenous knowledge', 'higher education']::text[], null, null, 'apa7', '2028-01-10', '2028-03-30', '2028-05-09T09:00:00Z', null, 'in_press', 3, 190, 41, null, true) on conflict (id) do nothing;
